public void update()
{
    TAMRebateLine rebateLineOrig = this.orig();

    next update();

    if (this.Occurrences > 0 && this.Occurrences != rebateLineOrig.Occurrences)
    {
        GUPRebateAmortizationScheduleDetail::createAmortizationScheduleDetails(this);
    }
}

public boolean validateWrite()
{
    boolean ret = next validateWrite();

    ret = this.checkNoMoreThanOneRebateLinesExistsForPrepaidLumpsum() && ret;
    ret = this.checkTotalRebateAmountGreaterThanZero() && ret;
    ret = this.checkOccurrenceGreaterThanZero() && ret;

    return ret;
}

private boolean checkTotalRebateAmountGreaterThanZero()
{
    boolean ret = true;
    if (this.RebateAmount <= 0 && this.TAMRebateTable().TAMRebateDeal().RebateTypeGUP != TAMRebateTypeGUP::Standard)
    {
        ret = warning("@GlobalUnifiedPricing:GUPRebateAmortizationTotalRebateAmountGreaterThanZero");
    }
    return ret;
}

private boolean checkOccurrenceGreaterThanZero()
{
    boolean ret = true;
    if (this.Occurrences <= 0 && this.TAMRebateTable().TAMRebateDeal().RebateTypeGUP != TAMRebateTypeGUP::Standard)
    {
        ret = warning("@GlobalUnifiedPricing:GUPRebateAmortizationZeroOccurrencesOnSchedule");
    }
    return ret;
}

private boolean checkNoMoreThanOneRebateLinesExistsForPrepaidLumpsum()
{
    boolean ret = true;
    TAMRebateLine rebateLine;
    TAMRebateDate rebateDate;
    TAMRebateTable rebateTable;
    TAMRebateDeal rebateDeal;

    select firstonly rebateLine
        exists join rebateDate
        where rebateLine.RefLineNum == rebateDate.LineNum
            && rebateLine.RebateId == rebateDate.RebateId
            && rebateLine.RebateId == this.RebateId
        exists join rebateTable
        where rebateDate.RebateId == rebateTable.RebateId
        exists join rebateDeal
        where rebateTable.RebateDeal == rebateDeal.RecId
            && rebateDeal.RebateTypeGUP == TAMRebateTypeGUP::PrepaidLumpsum;

    if (rebateLine.RecId && rebateLine.RecId != this.RecId)
    {
        ret = warning("@GlobalUnifiedPricing:TAMRebatePrepaidLumpsumMoreThanOneLineNotAllowed");
    }
    return ret;
}
